// Package postgres implements cluster.Store against PostgreSQL via
// jackc/pgx. The queries are generated by sqlc from queries.sql.
package postgres

import (
	"context"

	"github.com/jackc/pgx/v5/pgtype"
	"github.com/jackc/pgx/v5/pgxpool"

	"github.com/garamsh/garam/lib/errorx"
	"github.com/garamsh/garam/lib/grn"
	"github.com/garamsh/garam/platform/internal/cluster"
	"github.com/garamsh/garam/platform/internal/cluster/postgres/db"
	"github.com/garamsh/garam/platform/internal/pgxerr"
	"github.com/garamsh/garam/platform/internal/pgxtype"
)

// Store implements cluster.Store.
type Store struct {
	q *db.Queries
}

// Compile-time check that Store satisfies cluster.Store.
var _ cluster.Store = (*Store)(nil)

// New constructs a Postgres-backed cluster store.
func New(pool *pgxpool.Pool) *Store {
	return &Store{q: db.New(pool)}
}

// Create inserts the record and answers the row it wrote.
func (s *Store) Create(ctx context.Context, c *cluster.Cluster) (*cluster.Cluster, error) {
	row, err := s.q.CreateCluster(ctx, db.CreateClusterParams{
		Grn:         c.GRN.String(),
		OrgGrn:      c.Organization.String(),
		CreatedBy:   c.CreatedBy.String(),
		CreatedAt:   pgxtype.Timestamptz(c.CreatedAt),
		Name:        c.Name,
		Description: c.Description,
	})
	if err != nil {
		return nil, pgxerr.Classify(err, "create cluster", nil, nil)
	}
	return rowToCluster(row)
}

// Get reads the record under g.
func (s *Store) Get(ctx context.Context, g grn.GRN) (*cluster.Cluster, error) {
	row, err := s.q.GetCluster(ctx, g.String())
	if err != nil {
		return nil, pgxerr.Classify(err, "get cluster", cluster.ErrClusterNotFound, nil)
	}
	return rowToCluster(row)
}

// ListByOrg reads the organization's records, ordered by GRN.
func (s *Store) ListByOrg(ctx context.Context, orgGRN grn.GRN) ([]*cluster.Cluster, error) {
	rows, err := s.q.ListClustersByOrg(ctx, orgGRN.String())
	if err != nil {
		return nil, pgxerr.Classify(err, "list clusters", nil, nil)
	}
	out := make([]*cluster.Cluster, 0, len(rows))
	for _, row := range rows {
		c, err := rowToCluster(row)
		if err != nil {
			return nil, err
		}
		out = append(out, c)
	}
	return out, nil
}

// UpdateDetails writes the name and description patch sets.
func (s *Store) UpdateDetails(ctx context.Context, g grn.GRN, patch cluster.DetailsPatch) (*cluster.Cluster, error) {
	row, err := s.q.UpdateClusterDetails(ctx, db.UpdateClusterDetailsParams{
		Name:        optionalText(patch.Name()),
		Description: optionalText(patch.Description()),
		Grn:         g.String(),
	})
	if err != nil {
		return nil, pgxerr.Classify(err, "update cluster", cluster.ErrClusterNotFound, nil)
	}
	return rowToCluster(row)
}

// Delete removes the record under g.
func (s *Store) Delete(ctx context.Context, g grn.GRN) error {
	n, err := s.q.DeleteCluster(ctx, g.String())
	if err != nil {
		return pgxerr.Classify(err, "delete cluster", nil, nil)
	}
	if n == 0 {
		return cluster.ErrClusterNotFound
	}
	return nil
}

func optionalText(s *string) pgtype.Text {
	if s == nil {
		return pgtype.Text{}
	}
	return pgtype.Text{String: *s, Valid: true}
}

// rowToCluster parses a stored row. A GRN that GRNOf does not rebuild
// from its organization names no cluster of it, and is refused as
// storage that broke its own constraint.
func rowToCluster(row db.Cluster) (*cluster.Cluster, error) {
	g, err := grn.Parse(row.Grn)
	if err != nil {
		return nil, errorx.Wrap(err, "grn", errorx.KindInternal)
	}
	orgGRN, err := grn.Parse(row.OrgGrn)
	if err != nil {
		return nil, errorx.Wrap(err, "org grn", errorx.KindInternal)
	}
	if want, err := cluster.GRNOf(orgGRN, g.Identifier); err != nil || want != g {
		return nil, errorx.New(errorx.KindInternal, "stored cluster: grn "+g.String()+" is not a cluster of "+orgGRN.String())
	}
	createdBy, err := grn.Parse(row.CreatedBy)
	if err != nil {
		return nil, errorx.Wrap(err, "created by", errorx.KindInternal)
	}
	return &cluster.Cluster{
		GRN:          g,
		Organization: orgGRN,
		CreatedBy:    createdBy,
		CreatedAt:    row.CreatedAt.Time,
		Name:         row.Name,
		Description:  row.Description,
	}, nil
}
